questionvariables.text:
/* sc picks a scenario whose description determines the relation type:
   1 chairperson -> club (one-to-one), 2 student in exactly one club (many-to-one),
   3 patron -> clubs (one-to-many), 4 students in several clubs (many-to-many).
   One-to-one and many-to-one relations are functions. */
sc: rand([1, 2, 3, 4]);
correct: [onetoone, manytoone, onetomany, manytomany][sc];
/* The type a student gets by reading the record backwards (output to input). */
rev: [onetoone, onetomany, manytoone, manytomany][sc];
ta1: [[onetoone, is(correct=onetoone), "one-to-one"],
     [onetomany, is(correct=onetomany), "one-to-many"],
     [manytoone, is(correct=manytoone), "many-to-one"],
     [manytomany, is(correct=manytomany), "many-to-many"]];
ta2: [[isfn, is(sc<=2), "a function"], [notfn, is(sc>=3), "not a function"]];
tac1: first(mcq_correct(ta1));
tac2: first(mcq_correct(ta2));
/* For the wrong-answer test: an option that is neither correct nor the reversal. */
wrong1: if sc=1 then manytomany else onetoone;
